required = [PAD/"index.html", PAD/"fee-builder/index.html", PAD/"real-value/index.html", PAD/"revival-centre/index.html", PAD/"compliance/index.html", PAD/"funding-radar/index.html", PAD/"launches/index.html", CRYPTO/"worldzpad/index.html", PAD/"worldzpad.rules.json"]
for p in required:
    if not p.is_file() or p.stat().st_size < 300:
        raise SystemExit(f"WORLDZPAD_BUILD_FAILED={p.relative_to(ROOT)}")
for p in required[:-1]:
    text=p.read_text(encoding="utf-8")
    if '<meta name="viewport"' not in text or '<iframe' in text.lower():
        raise SystemExit(f"WORLDZPAD_PAGE_INVALID={p.relative_to(ROOT)}")
print(f"WORLDZPAD_BUILD=PASS pages={len(required)-1} execution_enabled=0 fee_max=4.00 protocol_fee_share=10pct_of_collected_fees")
